// Laser Security System
// LDR Module (DO) -> D7
// Active Buzzer -> D11
int ldr = 7;
int buzzer = 11;
void setup() {
  pinMode(ldr, INPUT);
  pinMode(buzzer, OUTPUT);
  digitalWrite(buzzer, LOW);   // Start with buzzer OFF
}
void loop() {
  int sensor = digitalRead(ldr);
  if (sensor == LOW) {
    // Laser beam is on the LDR
    digitalWrite(buzzer, LOW);   // Buzzer OFF
  }
  else {
    // Laser beam is broken
    digitalWrite(buzzer, HIGH);  // Buzzer ON
  }
  delay(50);   // Small delay for stable operation
}
